/**
 * Bulk Sealfast + Sunpool Specialty / International Couplings + Flanges — 2026-05-07
 *
 * 98 industrial coupling products from the Excel
 * `Industrial Hose Couplings - Cont2.xlsx` plus the linked Sealfast and
 * Sunpool product pages. Largest couplings batch yet — extends the
 * Sealfast brand from PR #82 / #83 with 32 more products and introduces
 * Sunpool (Taiwanese industrial coupling manufacturer) as a NEW brand
 * with 66 products.
 *
 * Brand split (derived from product-page link domains):
 *   - Sealfast (existing): 32 products — Sandblast (3), Crowfeet (7),
 *     Ground Joint (8), Ring Lock (4), Pin Lug Shank (3), Shank (5),
 *     Mender (1), Hose Nipples (1)
 *   - Sunpool (NEW): 66 products — Sandblast nylon (3), Guillemin (9),
 *     Composite Hose Fitting (6), KC Nipple (13), Storz (26), Flange (9)
 *
 * Adds:
 *   - 1 NEW brand: Sunpool (Taiwan, isAuthorizedDistributor: true)
 *   - 13 NEW sub-categories under the existing `industrial-hoses` master
 *     (positions 13–25)
 *   - 98 products (SKU patterns: IH-SB / IH-CRW / IH-GJ / IH-RL /
 *     IH-PLS / IH-SHK / IH-MND / IH-HN / IH-GUI / IH-COMP / IH-KC /
 *     IH-STZ / IH-FLG)
 *   - NEW megamenu sub-section "Specialty Couplings & Flanges" under
 *     the Industrial Hoses column (alongside existing "Hoses by Service"
 *     and "Couplings") with 13 leaves
 *
 * Reuses the `industrial-coupling-spec` template (10 text fields) from
 * PR #83 — the all-text design is flexible across all 13 coupling
 * families including the flanges.
 *
 * Run with:
 *   pnpm --filter @indus/db db:import src/imports/2026-05-07-sealfast-sunpool-couplings.ts --dry-run
 *   pnpm --filter @indus/db db:import src/imports/2026-05-07-sealfast-sunpool-couplings.ts
 */
import type {
  FaqEntry,
  ImportBatch,
  ProductImportPayload,
} from '../import/types'

// ── Common defaults ───────────────────────────────────────────────────────

const COMMON: Pick<
  ProductImportPayload,
  | 'status'
  | 'unitOfMeasure'
  | 'listPriceCurrency'
  | 'stockQty'
  | 'leadTimeDays'
> = {
  status: 'active',
  unitOfMeasure: 'each',
  listPriceCurrency: 'AED',
  stockQty: 0,
  leadTimeDays: 14,
}

function escape(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

// ── Type model ────────────────────────────────────────────────────────────

type CouplingInput = {
  sku: string
  title: string
  category: string
  brand: string
  family: string
  couplingType: string
  endA: string
  endB: string
  sizeRange: string
  materials: string
  workingPressure: string
  seal: string
  standards: string
  oneLiner: string
}

const FAMILY_CONTEXT: Record<string, string> = {
  'Sandblast Coupling':
    'Sandblast couplings connect compressed-air supply to a sandblast nozzle holder. NPSH-threaded hose ends and crowfoot-style couplers in aluminum or moulded nylon. Industrial standard for grit-blasting service in shipyards, foundries, surface preparation, and protective-coating shops. Pressure-rated for typical sandblast service (up to 300 psi).',
  'Crowfoot Coupling':
    'Crowfoot couplings are quick-connect industrial fittings with two cam-style lugs that engage a matching crowfoot — used extensively for compressed-air, water, and steam service in mining, construction, and industrial maintenance. Universal-pattern (also called Chicago / universal) so couplings interchange across manufacturers of the same size.',
  'Ground Joint Coupling':
    'Ground joint couplings ("Boss" couplings) use a metal-on-metal ground-seat seal — no gasket, no O-ring — for high-pressure steam and air service up to 600 psi. Three-piece assembly: hose stem (male shank), wing nut, and male / female spud. Industrial standard since the 1920s for steam-line service in refineries, food plants, and process industries.',
  'Ring Lock Coupling':
    'Ring-lock couplings use a spring-loaded ring with two lever handles to engage a male tip into a female cup — similar to Bauer pattern but with different lock geometry. Used for low-to-medium-pressure water transfer, irrigation, and dewatering service. Zinc-plated steel construction; sizes 2"–6". Confirm interchangeability with Bauer / Perrot couplings before pairing across manufacturers.',
  'Pin Lug Shank Coupling':
    'Pin-lug shank couplings use two lugs on the female nut to engage a wrench / spanner for hand-tight assembly. Aluminum body with brass nut for corrosion resistance. Common on garden / industrial water hoses, fire hose, and low-pressure transfer hoses. Threads typically NPSH (NPT for hose) per ANSI B1.20.7.',
  'Shank Coupling':
    'Shank couplings ("hose nipples") have a barbed shank one end and a threaded end the other. Long-shank variants give better hose-band grip on the host hose; short-shank for compact installation. Carbon steel or brass construction; sizes 1/2"–2".',
  'Hose Mender':
    'Hose menders are in-line splice fittings — barbed shank on both ends — for repairing a damaged hose section without replacing the full assembly. Brass construction for corrosion resistance.',
  'Hose Nipple':
    'Hose nipples are NPT × hose-barb fittings for connecting a male NPT thread to a hose end. Zinc-plated steel construction; sizes 1/4"–2".',
  'Guillemin Coupling':
    'Guillemin couplings are the French / European fire-service quick-connect standard (NF E 29-572). A camlock-style coupling with two cam levers that engage a matching half. Used extensively for fire-hose service in France, Spain, Italy, and parts of Africa / Middle East. Brass or aluminum construction; sizes 25–150 mm.',
  'Composite Hose Fitting':
    'Composite hose fittings terminate composite hoses (multi-ply polypropylene/polyester construction with internal + external wire helix per EN 13765:2015 Type 3). 316 stainless-steel construction with internal-wire engagement and external clamp lug nut. For oil tanker, vapour recovery, and chemical service. Pair with Camlock Type C/E spiral hose tail variants for cam-and-groove disconnect.',
  'KC Nipple / Industrial Hose Fitting':
    'KC nipples and heavy-duty hose fittings — Korean / Asian industrial pattern. Used for slurry, frac water, suction-discharge, and umbilical service. Carbon steel, aluminum, brass, or 316 SS construction. Sizes 1"–6". Includes specialty variants: hammer union (206), turn-back / fixed flange, and drag hose.',
  'Storz Coupling / Adapter':
    'Storz couplings are the German / European fire-service standard (DIN 14301) — the most widely used fire-hose connector outside the US. Single-piece coupling with two interlocking lugs that engage 90°. Aluminum (painted / hard-anodized), brass, or 316 SS construction. UL-listed FDC (Fire Department Connection) variants for US fire-protection service. Sizes Storz 25–150 (1-1/2"–6"). Suction (gray) or pressure (black) gaskets per service.',
  'Industrial Flange':
    'Industrial flanges are flat / raised-face plates with bolt holes for permanent pipe connections — welding neck, slip-on, socket weld, lap joint, threaded, flat, blind, and stub-end variants per ASME B16.5 (Class 150 / 300) and MSS SP-43. Carbon steel, 304/316 stainless, or gunmetal construction. Sizes 1/2" through 24".',
}

// ── HTML description builder ──────────────────────────────────────────────

function couplingHtml(g: CouplingInput): string {
  const brandLabel = g.brand === 'sealfast' ? 'Sealfast (USA)' : 'Sunpool (Taiwan)'
  return `<p>The <strong>${escape(g.title)}</strong> is a ${escape(g.family)} from the ${escape(brandLabel)} industrial coupling range. Indus Hydraulics is an authorised distributor in the UAE.</p>
<h3>Configuration</h3>
<ul>
<li><strong>Coupling family:</strong> ${escape(g.family)}</li>
<li><strong>Coupling type:</strong> ${escape(g.couplingType)}</li>
<li><strong>End A:</strong> ${escape(g.endA)}</li>
<li><strong>End B:</strong> ${escape(g.endB)}</li>
</ul>
<h3>Specifications</h3>
<ul>
<li><strong>Size range:</strong> ${escape(g.sizeRange)}</li>
<li><strong>Material:</strong> ${escape(g.materials)}</li>
<li><strong>Working pressure:</strong> ${escape(g.workingPressure)}</li>
<li><strong>Seal / clamp:</strong> ${escape(g.seal)}</li>
<li><strong>Applicable standards:</strong> ${escape(g.standards)}</li>
</ul>
<h3>Family context</h3>
<p>${escape(FAMILY_CONTEXT[g.family] ?? '')}</p>
<h3>How to order</h3>
<p>Specify (a) the size, (b) the body material if multiple options are listed, and (c) any thread / seal / gasket variant on the RFQ. Indus engineering will confirm the manufacturer part number against your application.</p>
<h3>Companion products</h3>
<p>Pair with the appropriate matching coupling half from the same family, plus the host hose / pipe / equipment. Browse the Sealfast and Sunpool industrial coupling ranges via the Indus Hydraulics catalogue.</p>`
}

// ── FAQs (8 per product) ──────────────────────────────────────────────────

function couplingFaqs(g: CouplingInput): FaqEntry[] {
  return [
    {
      q: `What is a ${g.family}?`,
      a: FAMILY_CONTEXT[g.family] ?? '',
    },
    {
      q: 'What are the end configurations?',
      a: `End A: ${g.endA}. End B: ${g.endB}.`,
    },
    {
      q: 'What sizes are available?',
      a: `${g.sizeRange}. Specify the exact size on the RFQ — manufacturer offers multiple sizes per part code; lead time depends on size and material.`,
    },
    {
      q: 'What material is the body?',
      a: g.materials,
    },
    {
      q: 'What is the working pressure?',
      a: g.workingPressure,
    },
    {
      q: 'What seal / clamp is supplied?',
      a: g.seal,
    },
    {
      q: 'Is this product compliant with industry standards?',
      a: g.standards,
    },
    {
      q: 'Lead time?',
      a: 'Common sizes are typically ex-Indus Dubai stock; less-common sizes / materials usually ship within 14-21 working days from RFQ confirmation.',
    },
  ]
}

// ── Translator ────────────────────────────────────────────────────────────

function makeCoupling(g: CouplingInput): ProductImportPayload {
  return {
    ...COMMON,
    sku: g.sku,
    title: g.title,
    brandSlug: g.brand,
    countryOfOrigin: g.brand === 'sealfast' ? 'USA' : 'Taiwan',
    categorySlug: g.category,
    specTemplateSlug: 'industrial-coupling-spec',
    descriptionShort: g.oneLiner.slice(0, 500),
    descriptionLong: couplingHtml(g),
    specs: {
      coupling_family: g.family,
      coupling_type: g.couplingType,
      end_a: g.endA,
      end_b: g.endB,
      size_range: g.sizeRange,
      materials_available: g.materials,
      working_pressure: g.workingPressure,
      seal_or_gasket: g.seal,
      applicable_standards: g.standards,
    },
    faqs: couplingFaqs(g),
    seoTitle: `${g.title} — ${g.brand === 'sealfast' ? 'Sealfast' : 'Sunpool'} | Indus Hydraulics`.slice(0, 200),
    seoDescription: g.oneLiner.slice(0, 500),
    focusKeyword: `${g.brand === 'sealfast' ? 'Sealfast' : 'Sunpool'} ${g.family}`,
  }
}

